package console

import (
	"context"
	"database/sql"
	"regexp"
	"strconv"
	"strings"
)

// SQL text is generated by this package. Values always remain bound parameters.
// SQLite remains the bounded resident cache; PostgreSQL owns durable events.
type eventDatabase struct {
	*sql.DB
	postgres bool
}

type queryTransaction struct {
	*sql.Tx
	postgres bool
}

func (d *eventDatabase) QueryContext(ctx context.Context, q string, args ...any) (*sql.Rows, error) {
	return d.DB.QueryContext(ctx, eventSQL(q, d.postgres), args...)
}
func (d *eventDatabase) QueryRowContext(ctx context.Context, q string, args ...any) *sql.Row {
	return d.DB.QueryRowContext(ctx, eventSQL(q, d.postgres), args...)
}
func (d *eventDatabase) ExecContext(ctx context.Context, q string, args ...any) (sql.Result, error) {
	return d.DB.ExecContext(ctx, eventSQL(q, d.postgres), args...)
}
func (t *queryTransaction) QueryContext(ctx context.Context, q string, args ...any) (*sql.Rows, error) {
	return t.Tx.QueryContext(ctx, eventSQL(q, t.postgres), args...)
}
func (t *queryTransaction) QueryRowContext(ctx context.Context, q string, args ...any) *sql.Row {
	return t.Tx.QueryRowContext(ctx, eventSQL(q, t.postgres), args...)
}
func (t *queryTransaction) ExecContext(ctx context.Context, q string, args ...any) (sql.Result, error) {
	return t.Tx.ExecContext(ctx, eventSQL(q, t.postgres), args...)
}

var slotSQL = regexp.MustCompile(`CAST\(ts/(\$[0-9]+) AS INTEGER\)`)
var timeRangeSQL = regexp.MustCompile(`\b([a-zA-Z_][a-zA-Z_0-9]*\.)?ts\s*(>=|<=|>|<)\s*(\$[0-9]+)`)

func eventSQL(q string, postgres bool) string {
	if !postgres {
		return q
	}
	q = strings.NewReplacer(
		"INSTR(", "strpos(",
		"hunt_metadata(raw,", "hunt_metadata(attack_metadata,",
		"tuple_hash(src,sport,dst,dport,proto)", "tuple_key",
		"flow_summary(app,proto,state,reason,sig)", "flow_label",
	).Replace(q)
	var out strings.Builder
	parameter := 0
	for i := 0; i < len(q); i++ {
		c := q[i]
		if c == '\'' || c == '"' {
			quote := c
			out.WriteByte(c)
			for i++; i < len(q); i++ {
				out.WriteByte(q[i])
				if q[i] == quote {
					if i+1 < len(q) && q[i+1] == quote {
						i++
						out.WriteByte(q[i])
						continue
					}
					break
				}
			}
		} else if c >= 'A' && c <= 'Z' || c >= 'a' && c <= 'z' || c == '_' {
			// Mirror timestamps are generated from the same event timestamp. Keep
			// lookups on the matching chunk and the existing session/time index.
			if strings.HasPrefix(q[i:], "a.ts=e.ts") {
				out.WriteString("(a.ts=e.ts AND a.event_time=e.event_time)")
				i += len("a.ts=e.ts") - 1
				continue
			}
			end := i + 1
			for end < len(q) && (q[end] >= 'A' && q[end] <= 'Z' || q[end] >= 'a' && q[end] <= 'z' || q[end] >= '0' && q[end] <= '9' || q[end] == '_') {
				end++
			}
			word := q[i:end]
			if strings.EqualFold(word, "user") {
				out.WriteString("\"user\"")
			} else {
				out.WriteString(word)
			}
			i = end - 1
		} else if c == '?' {
			parameter++
			out.WriteByte('$')
			out.WriteString(strconv.Itoa(parameter))
		} else {
			out.WriteByte(c)
		}
	}
	q = slotSQL.ReplaceAllString(out.String(), "CAST(trunc(ts/$1) AS BIGINT)")
	return timeRangeSQL.ReplaceAllStringFunc(q, func(match string) string {
		parts := timeRangeSQL.FindStringSubmatch(match)
		return "(" + match + " AND " + parts[1] + "event_time " + parts[2] + " to_timestamp(" + parts[3] + "::double precision/1000.0))"
	})
}
